#!/bin/sh
# Prints the Homebrew formula `rxh.rb` of a release, which installs the
# archives published by .github/workflows/release.yml: native binaries on
# macOS, static musl binaries on Linux.
#
# Usage: homebrew.sh VERSION SHA256SUMS
#
# SHA256SUMS is the checksum file of the release (`sha256sum` format) with
# the `rxh-VERSION-TARGET.tar.gz` archive of every target below.
set -eu

if [ "$#" -ne 2 ]; then
    echo "usage: $0 VERSION SHA256SUMS" >&2
    exit 2
fi
version=$1
sums=$2
dist=$(dirname "$0")

. "$dist/release-lib.sh"
check_version "$version"

# Prints the `url` and `sha256` lines of the archive of target $1.
archive() {
    file="rxh-$version-$1.tar.gz"
    sum=$(checksum "$sums" "$file")
    echo "      url \"$repository/releases/download/v$version/$file\""
    echo "      sha256 \"$sum\""
}
mac_arm=$(archive aarch64-apple-darwin)
mac_intel=$(archive x86_64-apple-darwin)
linux_arm=$(archive aarch64-unknown-linux-musl)
linux_intel=$(archive x86_64-unknown-linux-musl)

cat <<FORMULA
# Generated by dist/homebrew.sh for release $version.
class Rxh < Formula
  desc "Reverse proxy and layer 4 load balancer with live upstream management"
  homepage "$repository"
  version "$version"
  license "MIT"

  on_macos do
    on_arm do
$mac_arm
    end
    on_intel do
$mac_intel
    end
  end

  on_linux do
    on_arm do
$linux_arm
    end
    on_intel do
$linux_intel
    end
  end

  def install
    bin.install "rxh"
    man1.install Dir["man/*.1"]
    bash_completion.install "completions/rxh.bash" => "rxh"
    zsh_completion.install "completions/_rxh"
    fish_completion.install "completions/rxh.fish"
    # The [admin] table of the archive is for the systemd service: port 81
    # and a socket in /run, which a service of this user cannot have.
    inreplace "rxh.toml", /^# The members of the group rxh.*?^socket = "[^"]*"\n\n/m, ""
    # Homebrew keeps an edited etc file on upgrade and writes the new one as .default.
    pkgetc.install "rxh.toml"
  end

  service do
    run [opt_bin/"rxh", "run", "--config", etc/"rxh/rxh.toml"]
    keep_alive true
    log_path var/"log/rxh.log"
    error_log_path var/"log/rxh.log"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/rxh --version")
  end
end
FORMULA
